.coralbay-sim-container {
    padding: 28px;
    background: linear-gradient(170deg, #032b43 0%, #0a4c6e 35%, #065a60 70%, #0b525b 100%);
    min-height: 100vh;
    font-family: 'Segoe UI', -apple-system, 'Inter', sans-serif;
    color: #e0f2f1;
}
.coralbay-sim-header {
    background: linear-gradient(135deg, rgba(0,150,136,0.25) 0%, rgba(0,77,64,0.4) 100%);
    border: 1px solid rgba(128,203,196,0.2);
    border-radius: 20px;
    padding: 0;
    margin-bottom: 24px;
    overflow: hidden;
    position: relative;
}
.coralbay-sim-header::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
    background: linear-gradient(90deg, #00bfa5, #26c6da, #00897b);
}
.coralbay-sim-header-inner {
    padding: 32px 36px 28px;
    text-align: center;
}
.coralbay-sim-resort-badge {
    font-size: 2.4rem;
    margin-bottom: 8px;
}
.coralbay-sim-header h1 {
    color: #e0f7fa;
    font-size: 1.8rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    letter-spacing: 0.02em;
}
.coralbay-sim-subtitle {
    color: #80cbc4;
    font-size: 0.95rem;
    margin: 0;
    font-weight: 400;
    letter-spacing: 0.03em;
}
.coralbay-sim-period-counter {
    text-align: center;
    font-size: 1rem;
    color: #80cbc4;
    margin-bottom: 24px;
    font-weight: 600;
    letter-spacing: 0.05em;
}
.coralbay-sim-period-counter span {
    margin: 0 3px;
}
.coralbay-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
    gap: 14px;
    margin-bottom: 28px;
}
.coralbay-sim-kpi-card {
    background: rgba(0,77,64,0.35);
    border: 1px solid rgba(128,203,196,0.18);
    border-radius: 14px;
    padding: 20px 16px 18px;
    text-align: center;
    position: relative;
    transition: transform 0.2s ease, background 0.2s ease;
}
.coralbay-sim-kpi-card:hover {
    transform: translateY(-3px);
    background: rgba(0,77,64,0.5);
}
.coralbay-sim-kpi-icon {
    font-size: 1.4rem;
    margin-bottom: 6px;
}
.coralbay-sim-kpi-label {
    color: #80cbc4;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    margin-bottom: 8px;
    font-weight: 600;
}
.coralbay-sim-kpi-value {
    font-size: 1.7rem;
    font-weight: 700;
    color: #e0f7fa;
    transition: color 0.3s ease;
}
.coralbay-kpi-revenue .coralbay-sim-kpi-value { color: #4dd0e1; }
.coralbay-kpi-ebitda .coralbay-sim-kpi-value { color: #69f0ae; }
.coralbay-kpi-margin .coralbay-sim-kpi-value { color: #b2ff59; }
.coralbay-kpi-revpar .coralbay-sim-kpi-value { color: #ffcc80; }
.coralbay-kpi-occupancy .coralbay-sim-kpi-value { color: #ce93d8; }
.coralbay-sim-briefing {
    background: rgba(1,87,155,0.2);
    border: 1px solid rgba(79,195,247,0.2);
    border-left: 4px solid #26c6da;
    border-radius: 12px;
    padding: 24px 28px;
    margin-bottom: 28px;
    line-height: 1.65;
}
.coralbay-sim-briefing-badge {
    display: inline-block;
    background: rgba(38,198,218,0.15);
    color: #4dd0e1;
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    padding: 4px 12px;
    border-radius: 20px;
    margin-bottom: 14px;
}
.coralbay-sim-briefing-body {
    color: #b2dfdb;
    font-size: 0.92rem;
}
.coralbay-sim-controls {
    background: rgba(0,77,64,0.3);
    border: 1px solid rgba(128,203,196,0.15);
    border-radius: 16px;
    padding: 28px;
    margin-bottom: 28px;
}
.coralbay-sim-controls h3 {
    color: #e0f7fa;
    font-size: 1.1rem;
    font-weight: 600;
    margin: 0 0 20px 0;
    padding-bottom: 12px;
    border-bottom: 1px solid rgba(128,203,196,0.15);
}
.coralbay-sim-input-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
    margin-bottom: 16px;
}
.coralbay-sim-input-group {
    margin-bottom: 16px;
}
.coralbay-sim-input-group label {
    display: block;
    color: #80cbc4;
    font-size: 0.8rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.06em;
    margin-bottom: 8px;
}
.coralbay-sim-container input[type="number"],
.coralbay-sim-container select {
    width: 100%;
    padding: 10px 14px;
    background: rgba(0,37,46,0.6);
    border: 1px solid rgba(128,203,196,0.25);
    border-radius: 8px;
    color: #e0f7fa;
    font-size: 0.95rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    -moz-appearance: textfield;
}
.coralbay-sim-container input[type="number"]:focus,
.coralbay-sim-container select:focus {
    outline: none;
    border-color: #26c6da;
    box-shadow: 0 0 0 3px rgba(38,198,218,0.15);
}
.coralbay-sim-container select option {
    background: #0b3d4e;
    color: #e0f7fa;
}
.coralbay-sim-channel-note {
    color: #80cbc4;
    font-size: 0.85rem;
    font-style: italic;
    margin-bottom: 16px;
}
.coralbay-sim-btn-row {
    display: flex;
    gap: 12px;
    align-items: center;
    margin-top: 8px;
}
.coralbay-sim-submit {
    background: linear-gradient(135deg, #00897b, #00695c);
    border: none;
    color: #e0f7fa;
    font-weight: 600;
    font-size: 1rem;
    padding: 12px 32px;
    border-radius: 10px;
    letter-spacing: 0.03em;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
    cursor: pointer;
}
.coralbay-sim-submit:hover {
    transform: translateY(-2px);
    box-shadow: 0 6px 20px rgba(0,137,123,0.35);
    background: linear-gradient(135deg, #00897b, #00695c);
    color: #e0f7fa;
}
.coralbay-sim-undo {
    background: transparent;
    border: 1px solid rgba(128,203,196,0.3);
    color: #80cbc4;
    font-size: 0.85rem;
    padding: 8px 18px;
    border-radius: 8px;
    transition: background 0.2s ease;
    cursor: pointer;
}
.coralbay-sim-undo:hover {
    background: rgba(128,203,196,0.1);
    color: #b2dfdb;
}
.coralbay-sim-history {
    margin-bottom: 28px;
}
.coralbay-sim-container .table {
    background: rgba(0,77,64,0.2);
    border-radius: 12px;
    overflow: hidden;
    color: #b2dfdb;
    border: 1px solid rgba(128,203,196,0.12);
}
.coralbay-sim-container .table thead th {
    background: rgba(0,77,64,0.4);
    color: #80cbc4;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    border-bottom: 2px solid rgba(128,203,196,0.2);
    padding: 10px 12px;
    font-weight: 700;
}
.coralbay-sim-container .table tbody td {
    padding: 8px 12px;
    border-bottom: 1px solid rgba(128,203,196,0.08);
    font-size: 0.88rem;
}
.coralbay-sim-container .table tbody tr:hover {
    background: rgba(0,150,136,0.1);
}
.coralbay-sim-charts {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 28px;
}
.coralbay-sim-chart-wrapper {
    background: rgba(0,77,64,0.25);
    border: 1px solid rgba(128,203,196,0.12);
    border-radius: 14px;
    padding: 20px;
    min-height: 260px;
    position: relative;
}
.coralbay-sim-round-panel {
    animation: coralbayFadeIn 0.3s ease;
}
@keyframes coralbayFadeIn {
    from { opacity: 0; transform: translateY(8px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 768px) {
    .coralbay-sim-container { padding: 16px; }
    .coralbay-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .coralbay-sim-input-row { grid-template-columns: 1fr; }
    .coralbay-sim-charts { grid-template-columns: 1fr; }
    .coralbay-sim-header h1 { font-size: 1.4rem; }
    .coralbay-sim-kpi-value { font-size: 1.3rem; }
    .coralbay-sim-btn-row { flex-direction: column; }
}
/* ---- End-of-simulation debrief (v1.1.0) ---------------------------------- */
.coralbay-cm { text-align:center; color:#e0f7fa; font-family:-apple-system,'Segoe UI',sans-serif; padding:8px 4px 4px; }
.coralbay-cm-title { color:#4dd0e1; font-size:1.3rem; font-weight:700; letter-spacing:0.02em; margin-bottom:18px; }
.coralbay-cm-score-ring { width:130px; height:130px; margin:0 auto 14px; border:6px solid #4dd0e1; border-radius:50%;
    display:flex; flex-direction:column; align-items:center; justify-content:center; background:rgba(3,43,67,0.6); box-shadow:0 0 22px rgba(77,208,225,0.2); }
.coralbay-cm-score { font-size:2.7rem; font-weight:800; line-height:1; }
.coralbay-cm-score-max { font-size:0.78rem; color:#80cbc4; margin-top:2px; }
.coralbay-cm-verdict { font-size:1.2rem; font-weight:700; margin-bottom:4px; }
.coralbay-cm-grade { font-size:0.9rem; color:#80cbc4; font-weight:600; }
.coralbay-cm-metrics { display:flex; justify-content:center; flex-wrap:wrap; gap:12px; margin:20px 0 6px; }
.coralbay-cm-metric { background:rgba(0,77,64,0.45); border:1px solid rgba(128,203,196,0.25); border-radius:12px; padding:14px 18px; min-width:120px; }
.coralbay-cm-metric-label { color:#80cbc4; font-size:0.66rem; text-transform:uppercase; letter-spacing:0.08em; margin-bottom:6px; }
.coralbay-cm-metric-value { font-size:1.15rem; font-weight:700; color:#e0f7fa; }
.coralbay-cm-insights { text-align:left; background:rgba(0,77,64,0.35); border:1px solid rgba(128,203,196,0.25);
    border-left:3px solid #4dd0e1; border-radius:10px; padding:16px 20px; margin-top:18px; }
.coralbay-cm-insights-title { color:#4dd0e1; font-size:0.76rem; text-transform:uppercase; letter-spacing:0.08em; margin-bottom:10px; font-weight:700; }
.coralbay-cm-insights ul { margin:0; padding-left:20px; }
.coralbay-cm-insights li { color:#b2dfdb; font-size:0.9rem; line-height:1.55; margin-bottom:8px; }
.coralbay-cm-insights li:last-child { margin-bottom:0; }
@media (max-width:768px){ .coralbay-cm-metric { min-width:44%; } }

