(function() {
    'use strict';

    class CoralBayAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'La Temporada Baja';
            this.version = '1.1.0';
            this.ROOMS = 140;
            this.CAPACITY_WEEK = 280;
            this.PEAK_WEEKS = 22;
            this.LOW_WEEKS = 30;
            this.VAR_COST_PCT = 0.35;
            this.FIXED_COST = 2100000;
            this.COMPETITOR_PRICE = 1800;
            this.BASE_REVENUE = 180500000;
            this.BASE_EBITDA = 115225000;
            this.BASE_MARGIN = 63.8;
            // Score anchors: the round revenue model operates at ~$13-17M / 49-57% margin
            // / $256-336 RevPAR (measured across strategy archetypes). NOTE: these do NOT
            // reconcile with the BASE_* constants above (~10x higher) — a pre-existing
            // magnitude inconsistency in the sim's economic model (see report). The grade
            // is therefore anchored to the model's *own* realistic operating band so that
            // skill separates and the top tier is reachable, rather than to the broken
            // retention ratio (which pinned every learner near 10% -> "Needs Improvement").
            this.SCORE_REV_LOW = 12000000;
            this.SCORE_REV_HIGH = 18000000;
            this.SCORE_MARGIN_LOW = 45;
            this.SCORE_MARGIN_HIGH = 60;
            this.SCORE_REVPAR_LOW = 240;
            this.SCORE_REVPAR_HIGH = 340;
        }

        _t(key, vars) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') {
                    return window.mySimulation.t(key, vars);
                }
            } catch (e) {}
            return key;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    annualRevenue: 180500000,
                    ebitda: 115225000,
                    ebitdaMargin: 63.8,
                    revpar: 9.68,
                    avgOccupancy: 60,
                    peakPrice: 2500,
                    lowPrice: 1200,
                    peakOccupancy: 95,
                    lowOccupancy: 35,
                    channelMix: { direct: 20, ota: 35, tourOp: 35, local: 10 },
                    commissionSaved: 0,
                    elitePrice: 2500,
                    recPrice: 1600,
                    qualityLevel: 0,
                    revenueHistory: [],
                    ebitdaHistory: [],
                    marginHistory: [],
                    revparHistory: [],
                    performance: { overallScore: 0, grade: 'F', tier: 'needs_improvement' },
                    _snap: {}
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    peakPrice: 2500,
                    lowPrice: 1200,
                    directPct: 20,
                    otaPct: 35,
                    tourOpPct: 35,
                    localPct: 10,
                    marketingBudget: 50,
                    elitePrice: 2500,
                    recPrice: 1600,
                    qualityInvestment: 200,
                    lowMiscPrice: 1400,
                    lowProduct: 'leisure',
                    costReduction: 5
                };
            }

            // Re-render the (localized) briefing when the learner switches language
            // mid-simulation — the framework's setLanguage() only re-renders the history
            // table. _updateBriefing does not reset the decision inputs, so this is safe.
            var self = this;
            var onLang = function() {
                try { self._updateBriefing(window.mySimulation.state); } catch (e) {}
            };
            try {
                if (window.mySimulation && window.mySimulation.eventBus &&
                    typeof window.mySimulation.eventBus.on === 'function') {
                    window.mySimulation.eventBus.on('language:changed', onLang);
                }
            } catch (e) {}
            try { document.addEventListener('express:langchanged', onLang); } catch (e) {}

            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var round = (window.mySimulation.state.currentPeriod || 1);
            this._updateBriefing(window.mySimulation.state);

            if (round === 1) {
                var peakEl = document.getElementById('peakPriceInput');
                var lowEl = document.getElementById('lowPriceInput');
                if (peakEl) decisions.peakPrice = parseFloat(peakEl.value);
                if (lowEl) decisions.lowPrice = parseFloat(lowEl.value);
                if (!decisions.peakPrice || decisions.peakPrice < 1500 || decisions.peakPrice > 3000) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_peak_price'), 'warning');
                    return false;
                }
                if (!decisions.lowPrice || decisions.lowPrice < 600 || decisions.lowPrice > 2000) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_low_price'), 'warning');
                    return false;
                }
            }

            if (round === 2) {
                var dEl = document.getElementById('directPctInput');
                var oEl = document.getElementById('otaPctInput');
                var tEl = document.getElementById('tourOpPctInput');
                var lEl = document.getElementById('localPctInput');
                var mEl = document.getElementById('marketingInput');
                if (dEl) decisions.directPct = parseInt(dEl.value);
                if (oEl) decisions.otaPct = parseInt(oEl.value);
                if (tEl) decisions.tourOpPct = parseInt(tEl.value);
                if (lEl) decisions.localPct = parseInt(lEl.value);
                if (mEl) decisions.marketingBudget = parseInt(mEl.value);
                var total = decisions.directPct + decisions.otaPct + decisions.tourOpPct + decisions.localPct;
                if (total !== 100) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_channel_sum') + ' (' + total + '%)', 'warning');
                    return false;
                }
                if (decisions.marketingBudget < 0 || decisions.marketingBudget > 500) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_marketing'), 'warning');
                    return false;
                }
            }

            if (round === 3) {
                var eEl = document.getElementById('elitePriceInput');
                var rEl = document.getElementById('recPriceInput');
                var qEl = document.getElementById('qualityInput');
                if (eEl) decisions.elitePrice = parseFloat(eEl.value);
                if (rEl) decisions.recPrice = parseFloat(rEl.value);
                if (qEl) decisions.qualityInvestment = parseFloat(qEl.value);
                if (!decisions.elitePrice || decisions.elitePrice < 2000 || decisions.elitePrice > 3500) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_elite_price'), 'warning');
                    return false;
                }
                if (!decisions.recPrice || decisions.recPrice < 1000 || decisions.recPrice > 2200) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_rec_price'), 'warning');
                    return false;
                }
                if (decisions.elitePrice <= decisions.recPrice) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_price_order'), 'warning');
                    return false;
                }
            }

            if (round === 4) {
                var lmEl = document.getElementById('lowMiscPriceInput');
                var lpEl = document.getElementById('lowProductSelect');
                var crEl = document.getElementById('costReductionInput');
                if (lmEl) decisions.lowMiscPrice = parseFloat(lmEl.value);
                if (lpEl) decisions.lowProduct = lpEl.value;
                if (crEl) decisions.costReduction = parseFloat(crEl.value);
                if (!decisions.lowMiscPrice || decisions.lowMiscPrice < 600 || decisions.lowMiscPrice > 2000) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_low_misc_price'), 'warning');
                    return false;
                }
                if (decisions.costReduction < 0 || decisions.costReduction > 20) {
                    window.mySimulation.uiManager.showNotification(this._t('warn_cost_reduction'), 'warning');
                    return false;
                }
            }

            return true;
        }

        // ---- Scoring: persist a real 0-100 grade (v1.0.0 persisted none, so the server
        // graded every learner 0.0). Composite of EBITDA + revenue retention vs. the
        // pre-competition baseline and margin protection; underlying model unchanged. ----
        _tierFor(score) {
            if (score >= 82) return 'excellent';
            if (score >= 68) return 'strong';
            if (score >= 52) return 'competent';
            return 'needs_improvement';
        }
        _gradeFor(score) {
            if (score >= 90) return 'A';
            if (score >= 80) return 'B';
            if (score >= 70) return 'C';
            if (score >= 60) return 'D';
            return 'F';
        }
        _clamp01(x) { return Math.max(0, Math.min(1, x)); }
        _computeScore(finalRevenue, finalMargin, finalRevpar) {
            var revS = this._clamp01((finalRevenue - this.SCORE_REV_LOW) / (this.SCORE_REV_HIGH - this.SCORE_REV_LOW)) * 100;
            var marS = this._clamp01((finalMargin - this.SCORE_MARGIN_LOW) / (this.SCORE_MARGIN_HIGH - this.SCORE_MARGIN_LOW)) * 100;
            var rpS = this._clamp01((finalRevpar - this.SCORE_REVPAR_LOW) / (this.SCORE_REVPAR_HIGH - this.SCORE_REVPAR_LOW)) * 100;
            var score = Math.round(0.40 * revS + 0.35 * marS + 0.25 * rpS);
            if (score < 0) score = 0;
            if (score > 100) score = 100;
            return score;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = state.currentPeriod;

            // Undo/idempotency guard: snapshot cumulative domainState the first time a
            // period is processed; restore it if the period is reprocessed (undo+resubmit)
            // so the *History arrays are not double-pushed and cross-round reads
            // (e.g. R2 reads R1 revenue) recompute from the correct baseline. Forward
            // path byte-identical to v1.0.0 (verified).
            if (!ds._snap) ds._snap = {};
            if (ds._snap[round]) {
                var s = ds._snap[round];
                ds.annualRevenue = s.annualRevenue;
                ds.ebitda = s.ebitda;
                ds.ebitdaMargin = s.ebitdaMargin;
                ds.revpar = s.revpar;
                ds.avgOccupancy = s.avgOccupancy;
                ds.peakPrice = s.peakPrice;
                ds.lowPrice = s.lowPrice;
                ds.peakOccupancy = s.peakOccupancy;
                ds.lowOccupancy = s.lowOccupancy;
                ds.channelMix = { direct: s.channelMix.direct, ota: s.channelMix.ota, tourOp: s.channelMix.tourOp, local: s.channelMix.local };
                ds.commissionSaved = s.commissionSaved;
                ds.elitePrice = s.elitePrice;
                ds.recPrice = s.recPrice;
                ds.qualityLevel = s.qualityLevel;
                ds.revenueHistory = s.revenueHistory.slice();
                ds.ebitdaHistory = s.ebitdaHistory.slice();
                ds.marginHistory = s.marginHistory.slice();
                ds.revparHistory = s.revparHistory.slice();
            }
            ds._snap[round] = {
                annualRevenue: ds.annualRevenue, ebitda: ds.ebitda, ebitdaMargin: ds.ebitdaMargin,
                revpar: ds.revpar, avgOccupancy: ds.avgOccupancy, peakPrice: ds.peakPrice, lowPrice: ds.lowPrice,
                peakOccupancy: ds.peakOccupancy, lowOccupancy: ds.lowOccupancy,
                channelMix: { direct: ds.channelMix.direct, ota: ds.channelMix.ota, tourOp: ds.channelMix.tourOp, local: ds.channelMix.local },
                commissionSaved: ds.commissionSaved, elitePrice: ds.elitePrice, recPrice: ds.recPrice, qualityLevel: ds.qualityLevel,
                revenueHistory: ds.revenueHistory.slice(), ebitdaHistory: ds.ebitdaHistory.slice(),
                marginHistory: ds.marginHistory.slice(), revparHistory: ds.revparHistory.slice()
            };

            var revenue = 0;
            var costs = 0;
            var ebitda = 0;
            var margin = 0;
            var revpar = 0;
            var avgOcc = 0;
            var roundLabel = '';
            var detail = '';

            if (round === 1) {
                ds.peakPrice = d.peakPrice;
                ds.lowPrice = d.lowPrice;
                var peakOcc = this._calcPeakOccupancy(d.peakPrice);
                var lowOcc = this._calcLowOccupancy(d.lowPrice);
                ds.peakOccupancy = peakOcc;
                ds.lowOccupancy = lowOcc;
                var peakRev = this.CAPACITY_WEEK * (peakOcc / 100) * this.PEAK_WEEKS * d.peakPrice;
                var lowRev = this.CAPACITY_WEEK * (lowOcc / 100) * this.LOW_WEEKS * d.lowPrice;
                revenue = peakRev + lowRev;
                var varCost = revenue * this.VAR_COST_PCT;
                costs = varCost + this.FIXED_COST;
                ebitda = revenue - costs;
                margin = (ebitda / revenue) * 100;
                avgOcc = ((peakOcc * this.PEAK_WEEKS) + (lowOcc * this.LOW_WEEKS)) / 52;
                revpar = revenue / (this.ROOMS * 365);
                roundLabel = this._t('rlabel_1');
                detail = 'Peak ' + peakOcc.toFixed(0) + '% occ @ $' + d.peakPrice + ' | Low ' + lowOcc.toFixed(0) + '% occ @ $' + d.lowPrice;
            }

            if (round === 2) {
                var commDirect = 0.02;
                var commOTA = 0.15;
                var commTourOp = 0.25;
                var commLocal = 0.20;
                var baseRev = ds.annualRevenue;
                var mktBoost = Math.min(d.marketingBudget / 200, 1) * 0.03;
                var effDirectPct = d.directPct / 100;
                var effOTAPct = d.otaPct / 100;
                var effTourOpPct = d.tourOpPct / 100;
                var effLocalPct = d.localPct / 100;
                var netRevFactor = (effDirectPct * (1 - commDirect)) + (effOTAPct * (1 - commOTA)) + (effTourOpPct * (1 - commTourOp)) + (effLocalPct * (1 - commLocal));
                var prevNetFactor = (0.20 * (1 - commDirect)) + (0.35 * (1 - commOTA)) + (0.35 * (1 - commTourOp)) + (0.10 * (1 - commLocal));
                var directBoost = effDirectPct > 0.20 ? (effDirectPct - 0.20) * mktBoost * 10 : 0;
                netRevFactor = netRevFactor + directBoost;
                revenue = baseRev * netRevFactor / prevNetFactor;
                var mktCost = d.marketingBudget * 1000;
                var varCost2 = revenue * this.VAR_COST_PCT;
                costs = varCost2 + this.FIXED_COST + mktCost;
                ebitda = revenue - costs;
                margin = (ebitda / revenue) * 100;
                avgOcc = ds.avgOccupancy;
                revpar = revenue / (this.ROOMS * 365);
                ds.channelMix = { direct: d.directPct, ota: d.otaPct, tourOp: d.tourOpPct, local: d.localPct };
                ds.commissionSaved = (netRevFactor - prevNetFactor) * baseRev;
                roundLabel = this._t('rlabel_2');
                detail = 'Direct ' + d.directPct + '% | OTA ' + d.otaPct + '% | TourOp ' + d.tourOpPct + '% | Local ' + d.localPct + '%';
            }

            if (round === 3) {
                ds.elitePrice = d.elitePrice;
                ds.recPrice = d.recPrice;
                ds.qualityLevel = d.qualityInvestment;
                var qualityBonus = Math.min(d.qualityInvestment / 500, 1) * 8;
                var eliteOccBase = 45;
                var eliteOcc = Math.min(eliteOccBase + qualityBonus - ((d.elitePrice - 2500) / 100) * 2, 70);
                eliteOcc = Math.max(eliteOcc, 20);
                var recOccBase = 40;
                var recPriceDiff = (this.COMPETITOR_PRICE - d.recPrice) / 100;
                var recOcc = Math.min(recOccBase + recPriceDiff * 3 + qualityBonus * 0.5, 65);
                recOcc = Math.max(recOcc, 15);
                var totalPeakOcc = Math.min(eliteOcc + recOcc, 95);
                var peakEliteRev = this.CAPACITY_WEEK * (eliteOcc / 100) * this.PEAK_WEEKS * d.elitePrice;
                var peakRecRev = this.CAPACITY_WEEK * (recOcc / 100) * this.PEAK_WEEKS * d.recPrice;
                var lowRev3 = this.CAPACITY_WEEK * (ds.lowOccupancy / 100) * this.LOW_WEEKS * ds.lowPrice;
                revenue = peakEliteRev + peakRecRev + lowRev3;
                var varCost3 = revenue * this.VAR_COST_PCT;
                var qualityCost = d.qualityInvestment * 1000;
                costs = varCost3 + this.FIXED_COST + qualityCost;
                ebitda = revenue - costs;
                margin = (ebitda / revenue) * 100;
                avgOcc = ((totalPeakOcc * this.PEAK_WEEKS) + (ds.lowOccupancy * this.LOW_WEEKS)) / 52;
                revpar = revenue / (this.ROOMS * 365);
                roundLabel = this._t('rlabel_3');
                detail = 'Elite ' + eliteOcc.toFixed(0) + '% @ $' + d.elitePrice + ' | Rec ' + recOcc.toFixed(0) + '% @ $' + d.recPrice;
            }

            if (round === 4) {
                var productMultiplier = 1.0;
                if (d.lowProduct === 'weddings') productMultiplier = 1.25;
                if (d.lowProduct === 'groups') productMultiplier = 1.15;
                if (d.lowProduct === 'leisure') productMultiplier = 1.10;
                var lowBaseOcc = 30;
                var lowPriceFactor = (1400 - d.lowMiscPrice) / 200;
                var lowOcc4 = Math.min((lowBaseOcc + lowPriceFactor * 3) * productMultiplier, 55);
                lowOcc4 = Math.max(lowOcc4, 15);
                var eliteOcc4 = Math.min(45 + Math.min(ds.qualityLevel / 500, 1) * 8 - ((ds.elitePrice - 2500) / 100) * 2, 70);
                eliteOcc4 = Math.max(eliteOcc4, 20);
                var recOcc4 = Math.min(40 + ((this.COMPETITOR_PRICE - ds.recPrice) / 100) * 3 + Math.min(ds.qualityLevel / 500, 1) * 4, 65);
                recOcc4 = Math.max(recOcc4, 15);
                var peakEliteRev4 = this.CAPACITY_WEEK * (eliteOcc4 / 100) * this.PEAK_WEEKS * ds.elitePrice;
                var peakRecRev4 = this.CAPACITY_WEEK * (recOcc4 / 100) * this.PEAK_WEEKS * ds.recPrice;
                var lowRev4 = this.CAPACITY_WEEK * (lowOcc4 / 100) * this.LOW_WEEKS * d.lowMiscPrice;
                revenue = peakEliteRev4 + peakRecRev4 + lowRev4;
                var costReductionFactor = 1 - (d.costReduction / 100) * 0.7;
                var varCost4 = revenue * this.VAR_COST_PCT * costReductionFactor;
                var fixCost4 = this.FIXED_COST * costReductionFactor;
                costs = varCost4 + fixCost4;
                ebitda = revenue - costs;
                margin = (ebitda / revenue) * 100;
                var totalPeakOcc4 = Math.min(eliteOcc4 + recOcc4, 95);
                avgOcc = ((totalPeakOcc4 * this.PEAK_WEEKS) + (lowOcc4 * this.LOW_WEEKS)) / 52;
                revpar = revenue / (this.ROOMS * 365);
                roundLabel = this._t('rlabel_4');
                detail = 'Low ' + lowOcc4.toFixed(0) + '% @ $' + d.lowMiscPrice + ' (' + d.lowProduct + ') | Cost -' + d.costReduction + '%';
            }

            ds.annualRevenue = revenue;
            ds.ebitda = ebitda;
            ds.ebitdaMargin = margin;
            ds.revpar = revpar;
            ds.avgOccupancy = avgOcc;

            ds.revenueHistory.push(revenue);
            ds.ebitdaHistory.push(ebitda);
            ds.marginHistory.push(margin);
            ds.revparHistory.push(revpar);

            // Persist a real 0-100 score + letter grade so the server grade path reads a
            // score instead of coercing a missing value to 0.0. Written every period.
            var score = this._computeScore(revenue, margin, revpar);
            var tier = this._tierFor(score);
            var grade = this._gradeFor(score);
            ds.performance = { overallScore: score, grade: grade, tier: tier };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: round,
                roundLabel: roundLabel,
                revenue: revenue,
                costs: costs,
                ebitda: ebitda,
                margin: margin,
                revpar: revpar,
                avgOccupancy: avgOcc,
                detail: detail,
                overallScore: score,
                grade: grade,
                performanceTier: tier
            };
        }

        _calcPeakOccupancy(price) {
            var base = 75;
            var diff = (2500 - price) / 100;
            var occ = base + diff * 2.8;
            return Math.max(40, Math.min(occ, 95));
        }

        _calcLowOccupancy(price) {
            var base = 25;
            var diff = (1200 - price) / 100;
            var occ = base + diff * 2.5;
            return Math.max(10, Math.min(occ, 50));
        }

