        getPerformanceSummary(history) {
            if (!history.length) return {};
            var lastResult = history[history.length - 1].results || {};
            var finalRevenue = lastResult.revenue || 0;
            var finalEbitda = lastResult.ebitda || 0;
            var finalMargin = lastResult.margin || 0;
            var finalRevpar = lastResult.revpar || 0;
            var revenueRetention = (finalRevenue / this.BASE_REVENUE) * 100;
            var ebitdaRetention = (finalEbitda / this.BASE_EBITDA) * 100;

            var overallScore = (typeof lastResult.overallScore === 'number')
                ? lastResult.overallScore
                : this._computeScore(finalRevenue, finalMargin, finalRevpar);
            var tier = lastResult.performanceTier || this._tierFor(overallScore);
            var grade = lastResult.grade || this._gradeFor(overallScore);
