            else if (finalRevpar > 7) insights.push(this._t('insight_revpar_mid'));
            else insights.push(this._t('insight_revpar_low'));

            return {
                finalRevenue: finalRevenue,
                finalEbitda: finalEbitda,
                finalMargin: finalMargin,
                finalRevpar: finalRevpar,
                revenueRetention: revenueRetention,
                ebitdaRetention: ebitdaRetention,
