        _updateBriefing(state) {
            var round = Math.min((state.currentPeriod || 1), 4);
            if (round < 1) round = 1;
            var panels = ['round1Panel', 'round2Panel', 'round3Panel', 'round4Panel'];
            for (var i = 0; i < panels.length; i++) {
                var el = document.getElementById(panels[i]);
                if (el) el.style.display = (i === round - 1) ? 'block' : 'none';
            }
            var briefEl = document.getElementById('briefingText');
            if (!briefEl) return;
            briefEl.innerHTML = '<strong>' + this._t('briefing_r' + round + '_title') + '</strong><br><br>' + this._t('briefing_r' + round + '_body');
        }
    }

    function bootCoralBay() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new CoralBayAdapter(), {
            simulationType: 'coral_bay_revenue',
            maxPeriods: 4,
            autoSaveInterval: 30000
        });
    }
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bootCoralBay);
    } else {
        bootCoralBay();
    }

